int main() {
    int t,h,w;
    if (scanf("%d", &t)!=1) return 0;
    while (t--) {
        scanf("%d%d", &h, &w);
        const char *s=layout[(h-1)*8+w-1];
        for (int r=0;r<h;++r) {
            for (int c=0;c<w;++c) putchar(s[r*w+c]);
            putchar('\n');
        }
    }
    return 0;
}
